INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Erreichbarkeitsprobleme immer auf Timeouts zurückzuführen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Adressfehler möglich"}, {"text": "Ja", "correct": false, "because": "Mehrere Ursachen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft mir, Erreichbarkeitsprobleme zu erkennen?', 3, '[{"text": "ping", "correct": true, "because": "Testet Antwortzeit"}, {"text": "ifconfig", "correct": false, "because": "Nur Konfiguration"}, {"text": "dhclient", "correct": false, "because": "Adresszuweisung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ursachen führen zu Erreichbarkeitsproblemen?', 5, '[{"text": "Timeout", "correct": true, "because": "Keine Antwort erhalten"}, {"text": "Falsche Adresse", "correct": true, "because": "Ziel nicht existent"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein direkter Einfluss"}, {"text": "DNS-Cache", "correct": false, "because": "Nur Auflösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Timeout zeigt Erreichbarkeitsprobleme. b) Adressfehler sind immer vermeidbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Adressfehler oft menschlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse von Erreichbarkeitsproblemen?', 4, '[{"text": "Ping-Antwortzeit", "correct": false, "because": "Zeigt Timeout"}, {"text": "Zieladresse", "correct": false, "because": "Prüft Fehler"}, {"text": "Webserver-Logs", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Timeout immer ein Netzwerkproblem ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Zielgerät möglich"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich Netzwerk"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler zeigt eine falsche Adresse an?', 3, '[{"text": "Destination Unreachable", "correct": true, "because": "Ziel nicht gefunden"}, {"text": "Echo Reply", "correct": false, "because": "Erfolgreiche Antwort"}, {"text": "Time Exceeded", "correct": false, "because": "Hop-Limit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme deuten auf Erreichbarkeitsprobleme hin?', 5, '[{"text": "Request Timeout", "correct": true, "because": "Keine Antwort"}, {"text": "Destination Unreachable", "correct": true, "because": "Adressfehler"}, {"text": "Router Advertisement", "correct": false, "because": "SLAAC-spezifisch"}, {"text": "High Latency", "correct": false, "because": "Verzögerung, nicht Verlust"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Timeouts kommen von Firewalls. b) Adressfehler sind selten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Adressfehler häufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht zur Analyse von Erreichbarkeitsproblemen?', 4, '[{"text": "Ping", "correct": false, "because": "Testet Erreichbarkeit"}, {"text": "ICMPv6-Meldungen", "correct": false, "because": "Zeigt Fehler"}, {"text": "HTTP-Status", "correct": true, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Bedeutet ein Timeout immer einen Adressfehler?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch Netzwerk sein"}, {"text": "Ja", "correct": false, "because": "Verschiedene Ursachen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Test zeigt einen Timeout?', 4, '[{"text": "ping ohne Antwort", "correct": true, "because": "Request Timeout"}, {"text": "traceroute Erfolg", "correct": false, "because": "Ziel erreicht"}, {"text": "ipconfig Ausgabe", "correct": false, "because": "Nur Konfiguration"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Erreichbarkeitsprobleme nur bei IPv6 auftreten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IPv4 betroffen"}, {"text": "Ja", "correct": false, "because": "Protokollunabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Analyse von Erreichbarkeitsproblemen?', 3, '[{"text": "Ping-Ergebnisse", "correct": true, "because": "Zeigt Timeout"}, {"text": "DNS-Einträge", "correct": false, "because": "Sekundär"}, {"text": "Bandbreite", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Adressfehler führen zu Destination Unreachable. b) Timeouts sind immer Hardware-bedingt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Timeouts auch Netzwerk"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Analyse von Erreichbarkeitsproblemen?', 5, '[{"text": "Fehlerlokalisierung", "correct": true, "because": "Zeigt Problemquelle"}, {"text": "Netzwerkdiagnose", "correct": true, "because": "Testet Verbindung"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht enthalten"}, {"text": "IP-Zuweisung", "correct": false, "because": "Andere Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Erreichbarkeitsproblemen unwichtig?', 3, '[{"text": "ICMPv6-Meldungen", "correct": false, "because": "Zeigt Fehler"}, {"text": "Ping-Antwort", "correct": false, "because": "Diagnosekern"}, {"text": "Web-UI-Design", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Adressfehler einen Timeout verursachen?', 3, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Fehler"}, {"text": "Ja", "correct": false, "because": "Adressfehler ist separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob traceroute Erreichbarkeitsprobleme zeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Timeouts oder Unterbrechungen"}, {"text": "Nein", "correct": false, "because": "Teil der Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Meldung zeigt einen Adressfehler bei ICMPv6?', 4, '[{"text": "Destination Unreachable", "correct": true, "because": "Ziel nicht existent"}, {"text": "Time Exceeded", "correct": false, "because": "Hop-Limit"}, {"text": "Echo Reply", "correct": false, "because": "Erfolgreiche Antwort"}]');
